) AS vinculo(recorrido_nombre, zona_nombre)
JOIN LATERAL (SELECT id_recorrido FROM recorrido WHERE nombre = vinculo.recorrido_nombre ORDER BY id_recorrido DESC LIMIT 1) r ON TRUE
JOIN LATERAL (SELECT id_zona FROM zona WHERE nombre = vinculo.zona_nombre ORDER BY id_zona DESC LIMIT 1) z ON TRUE
WHERE NOT EXISTS (
  SELECT 1 FROM recorrido_zona rz WHERE rz.id_recorrido = r.id_recorrido AND rz.id_zona = z.id_zona
);

