JOIN LATERAL (
  SELECT id_atraccion FROM atraccion
  WHERE nombre = vinculo.atraccion_nombre
    AND ST_DWithin(geom_wkt, ST_SetSRID(ST_MakePoint(vinculo.lon, vinculo.lat), 4326), 0.00001)
  ORDER BY id_atraccion DESC LIMIT 1
) a ON TRUE
WHERE NOT EXISTS (
  SELECT 1 FROM recorrido_atracciones ra
  WHERE ra.id_recorrido = r.id_recorrido AND ra.id_atraccion = a.id_atraccion
);
